package com.example.textcolorchange; import android.graphics.Color; import android.os.Bundle; import android.view.View; import android.widget.TextView; import androidx.appcompat.app.AppCompatActivity; public class MainActivity extends AppCompatActivity { TextView tvColorText,tvColorName; int[] colors={Color.RED,Color.BLUE,Color.GREEN,Color.YELLOW,Color.MAGENTA}; String[] names={"RED","BLUE","GREEN","YELLOW","MAGENTA"}; int i=0; @Override protected void onCreate(Bundle b){super.onCreate(b);setContentView(R.layout.activity_main);tvColorText=findViewById(R.id.tvColorText);tvColorName=findViewById(R.id.tvColorName);} public void changeTextColor(View v){tvColorText.setTextColor(colors[i]);tvColorName.setText(names[i]);i=(i+1)%colors.length;}}
